describe('File Upload Success Checkmark', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should display a success checkmark when a file is fully uploaded', () => {
        const fileName = 'test-file.txt'; // Replace with the actual file name
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button[type="submit"]').click();
            cy.get('.upload-status').should('contain', 'Upload successful');
            cy.get('.checkmark-icon').should('be.visible');
        });
    });

    it('should not display a success checkmark when no file is uploaded', () => {
        cy.get('button[type="submit"]').click();
        cy.get('.upload-status').should('contain', 'No file selected');
        cy.get('.checkmark-icon').should('not.exist');
    });
});
